      heading: "How It Works",
      text: "Think of AI diagnostics like a supercharged detective. It sifts through medical images, lab results, and patient histories to spot anomalies. For example, AI can analyze thousands of X-rays in minutes, flagging potential issues for further review. It's like having a tireless assistant that never misses a clue."
